"""Transaction Detail By Account: drill from statement totals, totals tie out, rows open by mouse and keyboard.
Usage: python3 txdetail_ui.py /path/to/app/index.html"""
import asyncio, sys, os, tempfile
from playwright.async_api import async_playwright
APP = sys.argv[1] if len(sys.argv) > 1 else os.path.abspath(os.path.join(os.path.dirname(__file__), '..', '..', 'index.html'))
res = []
def check(ok, msg, info=''):
    res.append(ok); print(('  ok   ' if ok else '  FAIL ') + msg + ('' if ok else '  -> ' + str(info)))
async def main():
    async with async_playwright() as p:
        ctx = await p.chromium.launch_persistent_context(tempfile.mkdtemp(), viewport={'width': 1500, 'height': 900})
        pg = ctx.pages[0]; ev = pg.evaluate; errs = []; pg.on('pageerror', lambda e: errs.append(str(e)))
        await pg.goto('file://' + APP); await pg.wait_for_selector('#newco')
        await pg.fill('#newco input[name=name]', 'Detail Co'); s = pg.locator('#newco input[name=sample]')
        if await s.count(): await s.check()
        await pg.click('#newco button[type=submit]'); await pg.wait_for_function('OB.ui.book && OB.ui.book.transactions.length > 10', timeout=30000)
        money = "s => Math.round(parseFloat(s.replace(/[^0-9.-]/g, '')) * 100)"
        # Ctrl+P and Print send the real paginated report (a PDF made here) to the print window, not the screen (1.41)
        await ev("location.hash = '#/report/bs'"); await pg.wait_for_timeout(900)
        await pg.keyboard.press('Control+p'); await pg.wait_for_timeout(400)
        pdf = "(async () => { const f = document.getElementById('vb-print-frame'); if (!f) return ''; const u = new Uint8Array(await (await fetch(f.src)).arrayBuffer()); return String.fromCharCode(...u.slice(0, 4)); })()"
        check(await ev(pdf) == '%PDF' and not await ev("!!document.querySelector('.modal')"), 'Ctrl+P on the Balance Sheet prints the report PDF without asking for page setup')
        await ev("document.getElementById('vb-print-frame').remove(); location.hash = '#/report/tb'"); await pg.wait_for_timeout(900)
        await pg.click('[data-print]'); await pg.wait_for_timeout(400)
        check(await ev(pdf) == '%PDF', 'The Print button on any report does the same')
        # Looks, two levels, and account name -> ledger (1.39)
        await ev("location.hash = '#/report/bs'"); await pg.wait_for_timeout(900)
        await pg.click('.sb-look [data-look=grid]'); await pg.wait_for_timeout(500)
        check(await ev("document.querySelector('.sb-report').classList.contains('look-grid') && getComputedStyle(document.querySelector('tr.r-acc td.num')).borderLeftWidth !== '0px'"), 'View > Look > Full grid boxes every cell and is remembered')
        await pg.click('#st-view'); await pg.click('[data-coll=lv2]'); await pg.wait_for_timeout(300)
        check(await ev("!document.querySelector('tr.r-acc') && document.querySelectorAll('tr.r-coll').length > 1"), 'Show two levels folds every sub-group to one line')
        await pg.click('#st-view'); await pg.click('[data-coll=expand]'); await pg.wait_for_timeout(300)
        await pg.click('a.sb-ledger'); await pg.wait_for_timeout(700)
        check('#/report/gl?account=' in await ev('location.hash'), 'Clicking an account name opens that account ledger')
        await ev("location.hash = '#/report/bs'"); await pg.wait_for_timeout(700); await pg.click('.sb-look [data-look=classic]'); await pg.wait_for_timeout(400)
        # company layout 1-12 (Settings), three quick buttons on the report, two-sided totals level and equal
        check(await ev("[...document.querySelectorAll('.sb-look [data-look]')].map(x => x.textContent).join('|')") == 'Classic|Clean lines|Full grid', 'The report offers the three main layouts')
        await pg.click('.sb-look [data-look=lines]'); await pg.wait_for_timeout(400)   # a quick-button choice must not block a later change of the company setting
        await ev("location.hash = '#/settings'"); await pg.wait_for_timeout(600)
        check(await ev("document.querySelectorAll('[data-testid=co-look] option').length") == 12, 'Settings > Company lists the twelve statement layouts')
        await pg.select_option('[data-testid=co-look]', 'two'); await pg.click('[data-testid=co-look] >> xpath=ancestor::form//button[@type="submit"]'); await pg.wait_for_timeout(700)
        check(await ev("OB.ui.book.company.statementLook") == 'two', 'The layout is saved on the company')
        await ev("location.hash = '#/report/bs'"); await pg.wait_for_timeout(900)
        two = await ev("(() => { const t = [...document.querySelectorAll('.sb-two .two-t')]; return t.length === 2 && t[0].lastChild.textContent === t[1].lastChild.textContent && Math.abs(t[0].getBoundingClientRect().top - t[1].getBoundingClientRect().top) < 1 && Math.abs(t[0].getBoundingClientRect().bottom - t[1].getBoundingClientRect().bottom) < 1; })()")
        check(two, 'Two-sided Balance Sheet: both totals are equal and sit on the same line')
        check(await ev("[...document.querySelectorAll('.sb-look [data-look]')].map(x => x.textContent).join('|')") == 'Classic|Clean lines|Full grid|Two-sided', 'The company layout joins the quick buttons when it is not one of the three')
        await ev("location.hash = '#/report/pnl?by=month'"); await pg.wait_for_timeout(900)
        check(await ev("!document.querySelector('.sb-two') && document.querySelector('.sb-report').classList.contains('look-classic')"), 'With several columns the two-sided layout falls back to Classic')
        await ev("OB.ui.book.saveCompany({ statementLook: 'classic' })"); await pg.wait_for_timeout(300)

        await ev("location.hash = '#/report/pnl'"); await pg.wait_for_timeout(900)
        check(await ev("document.querySelector('.sb-report').classList.contains('grid-none')"), 'Statements have no gridlines by default')
        inc = await ev("(" + money + ")([...document.querySelectorAll('tr.r-tot')].find(r => /Total Income/.test(r.textContent)).querySelector('td.num').textContent)")
        await pg.click("tr.r-tot td.lbl >> text='Total Income'"); await pg.wait_for_timeout(900)
        check('#/report/txdetail' in await ev('location.hash') and 'node=s%3Aincome' in await ev('location.hash'), 'Clicking the Total Income row opens Transaction Detail By Account for Income')
        tot = await ev("(" + money + ")([...document.querySelectorAll('tr.txd-grand td.num')][1].textContent)")
        check(tot == inc, 'Detail TOTAL credit equals Total Income on the P&L', (tot, inc))
        n = await ev("document.querySelectorAll('tr.txd-row').length")
        check(n > 0, 'Detail lists the transactions', n)
        await pg.keyboard.press('ArrowDown'); await pg.keyboard.press('ArrowDown'); await pg.keyboard.press('ArrowDown'); await pg.wait_for_timeout(100)
        await pg.keyboard.press('Enter'); await pg.wait_for_timeout(700)
        check((await ev('location.hash')).startswith('#/txn/'), 'Arrow keys + Enter open the highlighted transaction')
        await ev("location.hash = '#/report/pnl'"); await pg.wait_for_timeout(800)
        await pg.click("tr.r-net td.lbl >> text='Net Income'"); await pg.wait_for_timeout(900)
        check('node=net%3Anet' in await ev('location.hash') and await ev("document.querySelectorAll('tr.txd-grp.d0').length") >= 2, 'Net Income opens the detail of every P&L section')
        await pg.click('tr.txd-row >> nth=0'); await pg.wait_for_timeout(700)
        check((await ev('location.hash')).startswith('#/txn/'), 'Clicking a detail row opens its transaction')
        await ev("location.hash = '#/report/bs'"); await pg.wait_for_timeout(800)
        await pg.click("text='TOTAL ASSETS'"); await pg.wait_for_timeout(900)
        ta = await ev("(" + money + ")([...document.querySelectorAll('tr.txd-grand td.num')][2].textContent)")
        await ev("location.hash = '#/report/bs'"); await pg.wait_for_timeout(800)
        bs = await ev("(" + money + ")([...document.querySelectorAll('tr.r-tot')].find(r => /TOTAL ASSETS/.test(r.textContent)).querySelector('td.num').textContent)")
        check(ta == bs, 'Balance sheet detail: TOTAL balance equals TOTAL ASSETS', (ta, bs))
        # one highlight at a time: the pointer and the arrow keys share a single row cursor
        await ev("location.hash = '#/report/txdetail'"); await pg.wait_for_timeout(900)
        rows = pg.locator('#main tbody tr'); bx = await rows.nth(4).bounding_box()
        await pg.mouse.move(bx['x'] + 200, bx['y'] + 5); await pg.wait_for_timeout(100)
        on_mouse = await ev("[...document.querySelectorAll('#main tr.kb-row')].map(r => r.matches(':hover'))")
        await pg.keyboard.press('ArrowDown'); await pg.keyboard.press('ArrowDown'); await pg.wait_for_timeout(100)
        after_keys = await ev("[...document.querySelectorAll('#main tr.kb-row')].map(r => r.matches(':hover'))")
        check(on_mouse == [True] and after_keys == [False], 'Pointer and arrow keys share one highlight (never two rows lit)', (on_mouse, after_keys))
        # dashboard drill-down: a month's income bar opens that month's income only, and its total matches the bar
        await ev("location.hash = '#/dashboard'"); await pg.wait_for_timeout(900)
        lab = await ev("[...document.querySelectorAll('[data-testid=bar-in]')].map(a => a.getAttribute('aria-label')).filter(l => !/\\$0\\.00$/.test(l))[0]")
        bar = float(lab.split('$')[1].replace(',', ''))
        await pg.click(f"[data-testid=bar-in][aria-label='{lab}']"); await pg.wait_for_timeout(900)
        hh = await ev('location.hash')
        tot = await ev("(" + money + ")([...document.querySelectorAll('tr.txd-grand td.num')][1].textContent)")
        check('node=net%3Ainc' in hh and 'range=custom' in hh and abs(tot / 100 - bar) < 0.005, 'Dashboard: a month\'s income bar opens that month\'s income, same total', (lab, hh, tot))
        dates = await ev("[...document.querySelectorAll('tr.txd-row')].map(r => r.children[1].textContent.trim())")
        m = lab.split(' income')[0]
        check(dates and all(d[:2] == {'Jan':'01','Feb':'02','Mar':'03','Apr':'04','May':'05','Jun':'06','Jul':'07','Aug':'08','Sep':'09','Oct':'10','Nov':'11','Dec':'12'}[m[:3]] for d in dates), 'Dashboard drill-down lists only that month', dates[:5])
        await ev("location.hash = '#/dashboard'"); await pg.wait_for_timeout(900)
        await pg.click('[data-testid=kpi-expense]'); await pg.wait_for_timeout(900)
        check('node=net%3Aexp' in await ev('location.hash') and 'Expenses' in await pg.inner_text('#main'), 'Dashboard Expenses figure opens the expense detail')
        check(not errs, 'No JavaScript errors', errs)
        await ctx.close()
    print(f'\n{sum(res)} passed, {len(res) - sum(res)} failed')
asyncio.run(main())
